export type WorldCommunityActivity = "high" | "medium" | "low";

export type WorldCommunityPromoHref =
  | "/ugc"
  | "/affiliates"
  | "/identity"
  | "/marketplace"
  | "/communities"
  | "/communities/live";

export type WorldCommunityRoomSeed = {
  slug: string;
  name: string;
  focus: string;
};

export type WorldCommunitySeed = {
  slug: string;
  name: string;
  category: string;
  tags: string[];
  topic: string;
  tagline: string;
  description: string;
  activity: WorldCommunityActivity;
  memberTier: 0 | 1 | 2 | 3 | 4 | 5 | 6 | 7;
  featured?: boolean;
  avatarPhoto: string;
  coverPhoto: string;
  rooms: WorldCommunityRoomSeed[];
  prompts: string[];
  pollQuestion: string;
  pollOptions: string[];
  promoHref: WorldCommunityPromoHref;
};

