export function assertWorldBlueprintIntegrity(): void {
  if (WORLD_COMMUNITY_SEEDS.length < 200) {
    throw new Error(`WORLD_COMMUNITY_SEEDS must have >= 200 entries (got ${WORLD_COMMUNITY_SEEDS.length})`);
  }

  const slugs = new Set<string>();
  const names = new Set<string>();

  for (const seed of WORLD_COMMUNITY_SEEDS) {
    if (!seed.slug || typeof seed.slug !== "string") throw new Error("Seed missing slug");
    if (FORBIDDEN_SLUGS.has(seed.slug)) throw new Error(`Forbidden slug: ${seed.slug}`);
    if (!/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(seed.slug)) {
      throw new Error(`Slug must be kebab-case: ${seed.slug}`);
    }
    if (slugs.has(seed.slug)) throw new Error(`Duplicate slug: ${seed.slug}`);
    slugs.add(seed.slug);

    if (!seed.name || typeof seed.name !== "string") throw new Error(`Seed ${seed.slug} missing name`);
    if (names.has(seed.name)) throw new Error(`Duplicate name: ${seed.name}`);
    names.add(seed.name);

    if (!ALLOWED_CATEGORIES.has(seed.category)) {
      throw new Error(`Invalid category for ${seed.slug}: ${seed.category}`);
    }
    if (!Array.isArray(seed.tags) || seed.tags.length === 0) {
      throw new Error(`Seed ${seed.slug} needs tags`);
    }
    for (const field of ["topic", "tagline", "description", "pollQuestion"] as const) {
      if (!seed[field] || typeof seed[field] !== "string") {
        throw new Error(`Seed ${seed.slug} missing ${field}`);
      }
    }
    if (seed.activity !== "high" && seed.activity !== "medium" && seed.activity !== "low") {
      throw new Error(`Seed ${seed.slug} has invalid activity`);
    }
    if (
      typeof seed.memberTier !== "number" ||
      seed.memberTier < 0 ||
      seed.memberTier > 7 ||
      !Number.isInteger(seed.memberTier)
    ) {
      throw new Error(`Seed ${seed.slug} has invalid memberTier`);
    }
    if (!seed.avatarPhoto?.startsWith("photo-") || !seed.coverPhoto?.startsWith("photo-")) {
      throw new Error(`Seed ${seed.slug} needs Unsplash photo-* ids`);
    }
    if (!Array.isArray(seed.rooms) || seed.rooms.length < 3 || seed.rooms.length > 6) {
      throw new Error(`Seed ${seed.slug} needs 3-6 rooms`);
    }
    for (const room of seed.rooms) {
      if (!room.slug || !room.name || !room.focus) {
        throw new Error(`Seed ${seed.slug} has incomplete room`);
      }
    }
    if (!Array.isArray(seed.prompts) || seed.prompts.length < 4 || seed.prompts.length > 6) {
      throw new Error(`Seed ${seed.slug} needs 4-6 prompts`);
    }
    if (!Array.isArray(seed.pollOptions) || seed.pollOptions.length < 4 || seed.pollOptions.length > 5) {
      throw new Error(`Seed ${seed.slug} needs 4-5 poll options`);
    }
    if (!ALLOWED_PROMO.has(seed.promoHref)) {
      throw new Error(`Seed ${seed.slug} has invalid promoHref`);
    }
  }
}
